SET XACT_ABORT ON;
BEGIN TRANSACTION;

IF OBJECT_ID('dbo.Roles','U') IS NULL CREATE TABLE dbo.Roles (RoleId INT IDENTITY PRIMARY KEY, RoleName NVARCHAR(50) NOT NULL CONSTRAINT UQ_Roles_RoleName UNIQUE);
IF OBJECT_ID('dbo.Departments','U') IS NULL CREATE TABLE dbo.Departments (DepartmentId INT IDENTITY PRIMARY KEY, DepartmentName NVARCHAR(150) NOT NULL CONSTRAINT UQ_Departments_Name UNIQUE, IsActive BIT NOT NULL CONSTRAINT DF_Departments_Active DEFAULT 1, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Departments_Created DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('dbo.Users','U') IS NULL CREATE TABLE dbo.Users (UserId INT IDENTITY PRIMARY KEY, SchoolId NVARCHAR(50) NOT NULL CONSTRAINT UQ_Users_SchoolId UNIQUE, FullName NVARCHAR(200) NOT NULL, Email NVARCHAR(320) NOT NULL CONSTRAINT UQ_Users_Email UNIQUE, DepartmentId INT NULL CONSTRAINT FK_Users_Departments REFERENCES dbo.Departments(DepartmentId), RoleId INT NOT NULL CONSTRAINT FK_Users_Roles REFERENCES dbo.Roles(RoleId), CustomerType NVARCHAR(100) NULL, IsActive BIT NOT NULL CONSTRAINT DF_Users_Active DEFAULT 1, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Users_Created DEFAULT SYSUTCDATETIME(), UpdatedAt DATETIME2 NOT NULL CONSTRAINT DF_Users_Updated DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('dbo.Categories','U') IS NULL CREATE TABLE dbo.Categories (CategoryId INT IDENTITY PRIMARY KEY, CategoryName NVARCHAR(150) NOT NULL CONSTRAINT UQ_Categories_Name UNIQUE, IsActive BIT NOT NULL CONSTRAINT DF_Categories_Active DEFAULT 1, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Categories_Created DEFAULT SYSUTCDATETIME(), UpdatedAt DATETIME2 NOT NULL CONSTRAINT DF_Categories_Updated DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('dbo.Products','U') IS NULL CREATE TABLE dbo.Products (ProductId INT IDENTITY PRIMARY KEY, CategoryId INT NOT NULL CONSTRAINT FK_Products_Categories REFERENCES dbo.Categories(CategoryId), SKU NVARCHAR(100) NOT NULL CONSTRAINT UQ_Products_SKU UNIQUE, ProductName NVARCHAR(200) NOT NULL, Description NVARCHAR(MAX) NULL, Price DECIMAL(12,2) NOT NULL, ImageUrl NVARCHAR(1000) NULL, IsFeatured BIT NOT NULL CONSTRAINT DF_Products_Featured DEFAULT 0, IsActive BIT NOT NULL CONSTRAINT DF_Products_Active DEFAULT 1, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Products_Created DEFAULT SYSUTCDATETIME(), UpdatedAt DATETIME2 NOT NULL CONSTRAINT DF_Products_Updated DEFAULT SYSUTCDATETIME(), CONSTRAINT CK_Products_Price CHECK (Price >= 0));
IF OBJECT_ID('dbo.ProductVariants','U') IS NULL CREATE TABLE dbo.ProductVariants (ProductVariantId INT IDENTITY PRIMARY KEY, ProductId INT NOT NULL CONSTRAINT FK_ProductVariants_Products REFERENCES dbo.Products(ProductId), VariantName NVARCHAR(100) NOT NULL, VariantSKU NVARCHAR(100) NOT NULL CONSTRAINT UQ_ProductVariants_SKU UNIQUE, IsActive BIT NOT NULL CONSTRAINT DF_ProductVariants_Active DEFAULT 1, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_ProductVariants_Created DEFAULT SYSUTCDATETIME(), UpdatedAt DATETIME2 NOT NULL CONSTRAINT DF_ProductVariants_Updated DEFAULT SYSUTCDATETIME(), CONSTRAINT UQ_ProductVariants_Product_Name UNIQUE(ProductId, VariantName));
IF OBJECT_ID('dbo.Inventory','U') IS NULL CREATE TABLE dbo.Inventory (ProductVariantId INT PRIMARY KEY CONSTRAINT FK_Inventory_Variants REFERENCES dbo.ProductVariants(ProductVariantId), PhysicalQuantity INT NOT NULL CONSTRAINT DF_Inventory_Physical DEFAULT 0, ReservedQuantity INT NOT NULL CONSTRAINT DF_Inventory_Reserved DEFAULT 0, ReorderLevel INT NOT NULL CONSTRAINT DF_Inventory_Reorder DEFAULT 0, UpdatedAt DATETIME2 NOT NULL CONSTRAINT DF_Inventory_Updated DEFAULT SYSUTCDATETIME(), CONSTRAINT CK_Inventory_Physical CHECK(PhysicalQuantity >= 0), CONSTRAINT CK_Inventory_Reserved CHECK(ReservedQuantity >= 0), CONSTRAINT CK_Inventory_Reorder CHECK(ReorderLevel >= 0), CONSTRAINT CK_Inventory_Reserved_Physical CHECK(ReservedQuantity <= PhysicalQuantity));
IF OBJECT_ID('dbo.ReservationStatuses','U') IS NULL CREATE TABLE dbo.ReservationStatuses (ReservationStatusId INT IDENTITY PRIMARY KEY, StatusName NVARCHAR(50) NOT NULL CONSTRAINT UQ_ReservationStatuses_Name UNIQUE);
IF OBJECT_ID('dbo.Reservations','U') IS NULL CREATE TABLE dbo.Reservations (ReservationId INT IDENTITY PRIMARY KEY, Reference NVARCHAR(100) NOT NULL CONSTRAINT UQ_Reservations_Reference UNIQUE, CustomerId INT NOT NULL CONSTRAINT FK_Reservations_Users REFERENCES dbo.Users(UserId), ReservationStatusId INT NOT NULL CONSTRAINT FK_Reservations_Statuses REFERENCES dbo.ReservationStatuses(ReservationStatusId), ExpiresAt DATETIME2 NOT NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Reservations_Created DEFAULT SYSUTCDATETIME(), UpdatedAt DATETIME2 NOT NULL CONSTRAINT DF_Reservations_Updated DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('dbo.ReservationItems','U') IS NULL CREATE TABLE dbo.ReservationItems (ReservationItemId INT IDENTITY PRIMARY KEY, ReservationId INT NOT NULL CONSTRAINT FK_ReservationItems_Reservations REFERENCES dbo.Reservations(ReservationId), ProductVariantId INT NOT NULL CONSTRAINT FK_ReservationItems_Variants REFERENCES dbo.ProductVariants(ProductVariantId), Quantity INT NOT NULL, UnitPrice DECIMAL(12,2) NOT NULL, CONSTRAINT CK_ReservationItems_Quantity CHECK(Quantity > 0), CONSTRAINT CK_ReservationItems_Price CHECK(UnitPrice >= 0));
IF OBJECT_ID('dbo.QueueTypes','U') IS NULL CREATE TABLE dbo.QueueTypes (QueueTypeId INT IDENTITY PRIMARY KEY, QueueTypeName NVARCHAR(50) NOT NULL CONSTRAINT UQ_QueueTypes_Name UNIQUE);
IF OBJECT_ID('dbo.QueueStatuses','U') IS NULL CREATE TABLE dbo.QueueStatuses (QueueStatusId INT IDENTITY PRIMARY KEY, StatusName NVARCHAR(50) NOT NULL CONSTRAINT UQ_QueueStatuses_Name UNIQUE);
IF OBJECT_ID('dbo.QueueEntries','U') IS NULL CREATE TABLE dbo.QueueEntries (QueueEntryId INT IDENTITY PRIMARY KEY, QueueNumber NVARCHAR(100) NOT NULL, CustomerId INT NOT NULL CONSTRAINT FK_QueueEntries_Users REFERENCES dbo.Users(UserId), ReservationId INT NOT NULL CONSTRAINT FK_QueueEntries_Reservations REFERENCES dbo.Reservations(ReservationId), QueueTypeId INT NOT NULL CONSTRAINT FK_QueueEntries_Types REFERENCES dbo.QueueTypes(QueueTypeId), QueueStatusId INT NOT NULL CONSTRAINT FK_QueueEntries_Statuses REFERENCES dbo.QueueStatuses(QueueStatusId), JoinedAt DATETIME2 NOT NULL CONSTRAINT DF_QueueEntries_Joined DEFAULT SYSUTCDATETIME(), CalledAt DATETIME2 NULL, CompletedAt DATETIME2 NULL);
IF OBJECT_ID('dbo.PaymentMethods','U') IS NULL CREATE TABLE dbo.PaymentMethods (PaymentMethodId INT IDENTITY PRIMARY KEY, PaymentMethodName NVARCHAR(100) NOT NULL CONSTRAINT UQ_PaymentMethods_Name UNIQUE, IsActive BIT NOT NULL CONSTRAINT DF_PaymentMethods_Active DEFAULT 1);
IF OBJECT_ID('dbo.TransactionStatuses','U') IS NULL CREATE TABLE dbo.TransactionStatuses (TransactionStatusId INT IDENTITY PRIMARY KEY, StatusName NVARCHAR(50) NOT NULL CONSTRAINT UQ_TransactionStatuses_Name UNIQUE);
IF OBJECT_ID('dbo.Transactions','U') IS NULL CREATE TABLE dbo.Transactions (TransactionId INT IDENTITY PRIMARY KEY, Reference NVARCHAR(100) NOT NULL CONSTRAINT UQ_Transactions_Reference UNIQUE, ReservationId INT NOT NULL CONSTRAINT FK_Transactions_Reservations REFERENCES dbo.Reservations(ReservationId), CustomerId INT NOT NULL CONSTRAINT FK_Transactions_Customers REFERENCES dbo.Users(UserId), StaffId INT NOT NULL CONSTRAINT FK_Transactions_Staff REFERENCES dbo.Users(UserId), PaymentMethodId INT NULL CONSTRAINT FK_Transactions_PaymentMethods REFERENCES dbo.PaymentMethods(PaymentMethodId), TransactionStatusId INT NOT NULL CONSTRAINT FK_Transactions_Statuses REFERENCES dbo.TransactionStatuses(TransactionStatusId), TotalAmount DECIMAL(12,2) NOT NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Transactions_Created DEFAULT SYSUTCDATETIME(), CONSTRAINT CK_Transactions_Total CHECK(TotalAmount >= 0));
IF OBJECT_ID('dbo.TransactionItems','U') IS NULL CREATE TABLE dbo.TransactionItems (TransactionItemId INT IDENTITY PRIMARY KEY, TransactionId INT NOT NULL CONSTRAINT FK_TransactionItems_Transactions REFERENCES dbo.Transactions(TransactionId), ProductVariantId INT NOT NULL CONSTRAINT FK_TransactionItems_Variants REFERENCES dbo.ProductVariants(ProductVariantId), Quantity INT NOT NULL, UnitPrice DECIMAL(12,2) NOT NULL, CONSTRAINT CK_TransactionItems_Quantity CHECK(Quantity > 0), CONSTRAINT CK_TransactionItems_Price CHECK(UnitPrice >= 0));
IF OBJECT_ID('dbo.InventoryMovementTypes','U') IS NULL CREATE TABLE dbo.InventoryMovementTypes (InventoryMovementTypeId INT IDENTITY PRIMARY KEY, MovementTypeName NVARCHAR(50) NOT NULL CONSTRAINT UQ_InventoryMovementTypes_Name UNIQUE);
IF OBJECT_ID('dbo.InventoryMovements','U') IS NULL CREATE TABLE dbo.InventoryMovements (InventoryMovementId BIGINT IDENTITY PRIMARY KEY, ProductVariantId INT NOT NULL CONSTRAINT FK_InventoryMovements_Variants REFERENCES dbo.ProductVariants(ProductVariantId), InventoryMovementTypeId INT NOT NULL CONSTRAINT FK_InventoryMovements_Types REFERENCES dbo.InventoryMovementTypes(InventoryMovementTypeId), PreviousQty INT NOT NULL, ChangeQty INT NOT NULL, ResultingQty INT NOT NULL, RelatedReference NVARCHAR(100) NULL, PerformedByUserId INT NULL CONSTRAINT FK_InventoryMovements_Users REFERENCES dbo.Users(UserId), Notes NVARCHAR(1000) NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_InventoryMovements_Created DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('dbo.Notifications','U') IS NULL CREATE TABLE dbo.Notifications (NotificationId BIGINT IDENTITY PRIMARY KEY, RecipientUserId INT NOT NULL CONSTRAINT FK_Notifications_Users REFERENCES dbo.Users(UserId), NotificationType NVARCHAR(100) NOT NULL, Title NVARCHAR(250) NOT NULL, Message NVARCHAR(MAX) NOT NULL, RelatedEntity NVARCHAR(100) NULL, RelatedEntityId INT NULL, DeliveryStatus NVARCHAR(50) NULL, IsRead BIT NOT NULL CONSTRAINT DF_Notifications_Read DEFAULT 0, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Notifications_Created DEFAULT SYSUTCDATETIME(), ReadAt DATETIME2 NULL);
IF OBJECT_ID('dbo.AuditLogs','U') IS NULL CREATE TABLE dbo.AuditLogs (AuditLogId BIGINT IDENTITY PRIMARY KEY, UserId INT NULL CONSTRAINT FK_AuditLogs_Users REFERENCES dbo.Users(UserId), Action NVARCHAR(100) NOT NULL, Entity NVARCHAR(100) NOT NULL, EntityId NVARCHAR(100) NULL, PreviousValue NVARCHAR(MAX) NULL, NewValue NVARCHAR(MAX) NULL, Details NVARCHAR(MAX) NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_AuditLogs_Created DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('dbo.SystemSettings','U') IS NULL CREATE TABLE dbo.SystemSettings (SettingKey NVARCHAR(100) PRIMARY KEY, SettingValue NVARCHAR(500) NOT NULL, DataType NVARCHAR(50) NOT NULL, Description NVARCHAR(500) NULL, UpdatedAt DATETIME2 NOT NULL CONSTRAINT DF_SystemSettings_Updated DEFAULT SYSUTCDATETIME(), UpdatedByUserId INT NULL CONSTRAINT FK_SystemSettings_Users REFERENCES dbo.Users(UserId));

IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Users_RoleId') CREATE INDEX IX_Users_RoleId ON dbo.Users(RoleId);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Products_Category_Active_Featured') CREATE INDEX IX_Products_Category_Active_Featured ON dbo.Products(CategoryId,IsActive,IsFeatured);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_ProductVariants_ProductId') CREATE INDEX IX_ProductVariants_ProductId ON dbo.ProductVariants(ProductId);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Reservations_Customer_Status_Expires') CREATE INDEX IX_Reservations_Customer_Status_Expires ON dbo.Reservations(CustomerId,ReservationStatusId,ExpiresAt);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_ReservationItems_Reservation_Variant') CREATE INDEX IX_ReservationItems_Reservation_Variant ON dbo.ReservationItems(ReservationId,ProductVariantId);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_QueueEntries_Customer_Status_Joined') CREATE INDEX IX_QueueEntries_Customer_Status_Joined ON dbo.QueueEntries(CustomerId,QueueStatusId,JoinedAt) INCLUDE(ReservationId,QueueTypeId);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Transactions_Customer_Created') CREATE INDEX IX_Transactions_Customer_Created ON dbo.Transactions(CustomerId,CreatedAt) INCLUDE(StaffId,ReservationId);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_TransactionItems_TransactionId') CREATE INDEX IX_TransactionItems_TransactionId ON dbo.TransactionItems(TransactionId);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_InventoryMovements_Variant_Created') CREATE INDEX IX_InventoryMovements_Variant_Created ON dbo.InventoryMovements(ProductVariantId,CreatedAt);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Notifications_User_Read_Created') CREATE INDEX IX_Notifications_User_Read_Created ON dbo.Notifications(RecipientUserId,IsRead,CreatedAt);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_AuditLogs_User_Entity_Created') CREATE INDEX IX_AuditLogs_User_Entity_Created ON dbo.AuditLogs(UserId,Entity,CreatedAt);

COMMIT;
